/**
 * Función para seleccionar si el usuario actualmente trabaja en la experiencia laboral.
 * 
 * @param {boolean} seleccionado Indica si el checkbox "Actualmente trabajo aquí" está seleccionado.
 * @return {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 * @author Jair Carvajal
 */
function seleccionarActualmenteTrabajo(seleccionado) {
    let fecha_inicio_existente = $('#fecha_inicio_experiencia').length ? $('#fecha_inicio_experiencia')[0]._flatpickr : null;
    if (fecha_inicio_existente) fecha_inicio_existente.destroy();
    let fecha_fin_existente = $('#fecha_fin_experiencia').length ? $('#fecha_fin_experiencia')[0]._flatpickr : null;
    if (fecha_fin_existente) fecha_fin_existente.destroy();
    $('#fechas-trabajo-experiencia').empty();
    if (seleccionado) {
        $('#fechas-trabajo-experiencia').append(`
            <div class="col-12 mt-3">
                ${crearSelectorMesAnio({
                    id: 'fecha_inicio_experiencia',
                    name: 'fecha_inicio_experiencia',
                    placeholder: 'mm/yyyy',
                    disabled: false,
                    required: true,
                    input_container_class: 'mb-2',
                    label: 'Fecha de inicio',
                    icono2: '<i class="bi bi-calendar4 input-icono2 pointer"></i>',
                })}
            </div>
        `);
    } else {
        $('#fechas-trabajo-experiencia').append(`
            <div class="col-12 col-md-6 mt-3">
                ${crearSelectorMesAnio({
                    id: 'fecha_inicio_experiencia',
                    name: 'fecha_inicio_experiencia',
                    placeholder: 'mm/yyyy',
                    disabled: false,
                    required: true,
                    input_container_class: 'mb-2',
                    label: 'Fecha de inicio',
                    icono2: '<i class="bi bi-calendar4 input-icono2 pointer"></i>',
                })}
            </div>
            <div class="col-12 col-md-6 mt-3">
                ${crearSelectorMesAnio({
                    id: 'fecha_fin_experiencia',
                    name: 'fecha_fin_experiencia',
                    placeholder: 'mm/yyyy',
                    disabled: false,
                    required: true,
                    input_container_class: 'mb-2',
                    label: 'Fecha de finalización',
                    icono2: '<i class="bi bi-calendar4 input-icono2 pointer"></i>',
                })}
            </div>
        `);
    }
    inicializarFlatpickr();

