@section('scripts')
    <link href="https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.5.12/cropper.min.css" rel="stylesheet">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/cropperjs/1.5.12/cropper.min.js"></script>
    <script type="text/javascript">
        const USUARIO = @json($usuario);
        let modalidades_estudios = [
            {id: 'Diurna', nombre: 'Diurna'},
            {id: 'Nocturna', nombre: 'Nocturna'}
        ];
        let niveles_educativos = @json($niveles_educativos);
        let discapacidades = @json($discapacidades);
        let revision_hv_ia = {{ $revision_hv_ia ? 'true' : 'false' }};
        let revision_hv = {{ $revision_hv ? 'true' : 'false' }};
        let creditos_disponibles = {{ $creditos_disponibles ? 'true' : 'false' }};
        let validar_contrasena = true;
        let idiomas = [
            {'id': 1, 'nombre': 'Inglés'},
            {'id': 2, 'nombre': 'Portugués'},
            {'id': 3, 'nombre': 'Francés'},
            {'id': 4, 'nombre': 'Alemán'},
            {'id': 5, 'nombre': 'Mandarín'},
            {'id': 6, 'nombre': 'Italiano'},
            {'id': 7, 'nombre': 'Ruso'},
            {'id': 8, 'nombre': 'Árabe'},
        ];
        $(document).ready(function () {

            const BORRADOR_ID = 'borrador_completar_datos_' + USUARIO.id;
            var borrador_existente = localStorage.getItem(BORRADOR_ID);

            if (borrador_existente) {
                var datos_borrador = JSON.parse(borrador_existente);
                var tiempo_expiracion = 24 * 60 * 60 * 1000;

                if (Date.now() - datos_borrador.timestamp < tiempo_expiracion) {
                    setTimeout(function() {
                        restaurarBorradorLocalStorage();
                    }, 500)
                }
            }

            iniciarAutoGuardado();

            consultarPaisesListadoCompleto();
            $('#nombres').val(USUARIO.nombres.trim());
            $('#apellidos').val(USUARIO.apellidos.trim());
            $('#fecha_nacimiento')[0]._flatpickr.setDate(USUARIO?.fecha_nacimiento);
            $('#genero_id').val(USUARIO.genero_id).trigger('change').trigger('select2:select');
            $('#telefono').val(USUARIO.telefono);
            $('#direccion').val(USUARIO.direccion);
            $('#tipo_documento_id').val(USUARIO.tipo_documento_id).trigger('change').trigger('select2:select');
            $('#documento').val(USUARIO.documento);
            $('#email').val(USUARIO.email);
            $('#email-enviado').text(USUARIO.email);
            establecerDatosComponentePaisesDepartamentosCiudades({
                pais: {
                    html_id: 'pais_id',
                    value: USUARIO.ciudad?.departamento?.pais_id ? USUARIO.ciudad.departamento.pais_id : null
                },
                departamento: {
                    html_id: 'departamento_id',
                    value: USUARIO.ciudad?.departamento_id ? USUARIO.ciudad.departamento_id : null
                },
                ciudad: {
                    html_id: 'ciudad_id',
                    value: USUARIO.ciudad?.id ? USUARIO.ciudad.id : null
                },
            });
            let politicas_aceptadas = false;
            if (USUARIO.politicas_aceptadas.some(p => p.id === 1)) {
                politicas_aceptadas = true;
                $('#aceptar_politicas').prop('checked', politicas_aceptadas);
            }
            let aceptar_teminos_condiciones = false;
            if (USUARIO.politicas_aceptadas.some(p => p.id === 2)) {
                aceptar_teminos_condiciones = true;
                $('#aceptar_teminos_condiciones').prop('checked', aceptar_teminos_condiciones);
            }
            if (politicas_aceptadas && aceptar_teminos_condiciones) {
                $('#btn-siguiente-datos-generales').prop('disabled', false);
                $('#titulo-tab-pasos-usuario-datos-acceso').prop('disabled', false);
                $('#contenedor-texto-verificacion-cuenta').addClass('d-none');
                $('#contenedor-mensaje-verificar').addClass('d-none');
                $('#contenedor-boton-verificar-correo').addClass('d-none');
                usuario_verificado = true;
                validar_contrasena = false;
            }
        });

    </script>

