function crearSelectorMesAnio(componente) {
    let icono_2_procesado = componente.icono2;
    if (componente.icono2) {
        if (componente.icono2.includes('onclick=')) {
            icono_2_procesado = componente.icono2.replace(
                /onclick="[^"]*"/,
                `onclick="activarDatePickerCercano(this);"`
            );
        } else {
            icono_2_procesado = componente.icono2.replace(
                '>',
                ` onclick="activarDatePickerCercano(this);">`
            );
        }
    }

    var html = `
        <div
            class="
                input-container
                ${componente.icono || componente.icono2 ? 'input-icon' : ''}
                ${componente.input_container_class ? componente.input_container_class : ''}
            "
            ${componente.input_container_style ? `style="${componente.input_container_style}"` : ''}
        >
            ${componente.icono ? `${componente.icono}` : ''}
            <input
                ${componente.id ? `id="${componente.id}"` : ''}
                ${componente.name ? `name="${componente.name}"` : ''}
                class="rounded-2 text-body-2 input-filtro flatpickr-month-year ${componente.class ? componente.class : ''}"
                placeholder="${componente.placeholder ? componente.placeholder : ''}"
                ${componente.disabled == true ? `disabled` : ''}
                ${componente.required == true ? `required` : ''}
                ${componente.onchange ? `onchange="${componente.onchange}"` : ''}
                ${componente.value ? `value="${componente.value}"` : ''}
                ${componente.style ? `style="${componente.style}"` : ''}
                ${componente.min ? `min="${componente.min}"` : ''}
                ${componente.max ? `max="${componente.max}"` : ''}
                ${componente.adicional ? componente.adicional : ''}
            `;

    if (componente.data) {
        componente.data.forEach(valor => {
            html += ` data-${valor.texto}="${valor.value}" `;
        });
    }

    html += `
            >
            ${icono_2_procesado ? `${icono_2_procesado}` : ''}
            ${componente.icono4 ? `<div class="icono-4">${componente.icono4}</div>` : ''}
            ${componente.label ? `<label ${componente.id ? `for="${componente.id}"` : ''} class="label-flotante text-body-2">${componente.label} ${componente.required === undefined ? '' : componente.required ? '*' : '(Opcional)'}</label>` : ''}
        </div>
    `;
    return html;
}

/**
 * Función helper para activar el datepicker más cercano
 *
 * @param {HTMLElement} icono_elemento Elemento DOM del icono desde el cual buscar el datepicker más cercano
 * @returns {string} Componente de input con icono de calendario.
 * @author Andres Gonzalez
 */
function activarDatePickerCercano(icono_elemento) {
    const contenedor = icono_elemento.closest('.input-container');
    if (contenedor) {
        const input = contenedor.querySelector('input');
        if (input) {
            if (input._flatpickr) {
                input._flatpickr.open();
            } else {
                input.click();
                input.focus();
            }
        }
    }
}

