});

let usuario_verificado = false;
let respuesta_codigo = [];
let validando_codigo = false;
let estudios = [];
let experiencias = [];
let certificados_laborales = [];
let indice_editar = null;

let estado_validacion_contrasena = {
    longitud_minima:       false,
    letra_mayuscula:       false,
    letra_minuscula:       false,
    tiene_numero:          false,
    caracter_especial:     false,
