                    name: 'salario',
                    class: 'cleave',
                    input_container_class: 'mb-3 mb-md-0',
                    label: 'Desde',
                    placeholder: '',
                    step: 0.01,
                    required: true,
                    minlength: 3,
                    maxlength: 10,
                    onchange: `validarRangoSalario()`,
                    data: [{
                        texto: 'simbolo-cleave',
                        value: ''
                    }],
                    icono: '<i class="bi bi-currency-dollar input-icono1"></i>',
                })}
            </div>
            <div class="col-12 col-md-6">
                ${crearInput({
                    id: 'salario_maximo',
                    name: 'salario_maximo',
                    class: 'cleave',
                    input_container_class: 'mb-0',
                    label: 'Hasta',
                    placeholder: '',
                    min: 0,
                    step: 0.01,
                    required: true,
                    minlength: 3,
                    maxlength: 10,
                    onchange: `validarRangoSalario()`,
                    data: [{
                        texto: 'simbolo-cleave',
                        value: ''
                    }],
                    icono: '<i class="bi bi-currency-dollar input-icono1"></i>',
                })}
            </div>
        `);
    }
    inputsCleave();
}

/**
 * Valida el rango de salario
 * @description Verifica que el salario máximo sea mayor o igual al salario mínimo
 * @returns {boolean} true si es válido, false en caso contrario
 * @author José Manuel Jiménez
 */
function validarRangoSalario() {
    if ($('input[name="tipo_salario"]:checked').val() !== 'rango') {
        return true;
    }
    let salario_desde = parseFloat(limpiarCleave($('#salario').val())) || 0;
    let salario_maximo = parseFloat(limpiarCleave($('#salario_maximo').val())) || 0;
    let $input_hasta = $('#salario_maximo');
    let $contenedor_hasta = $input_hasta.closest('.input-container');
    $input_hasta.removeClass('error');
    $contenedor_hasta.siblings('label[for="salario_maximo"].error').remove();
    if (salario_desde > 99 && salario_maximo > 99 && salario_desde >= salario_maximo) {
        setTimeout(() => {
            $input_hasta.addClass('error');
            $contenedor_hasta.after('<label for="salario_maximo" class="error text-red-cta">El salario hasta no debe ser menor o igual al salario desde</label>');
            return false;
        }, 100);
    }
    return true;
}

/**
 * Función para seleccionar si el usuario posee discapacidad.
 * 
 * @param {boolean} posee_discapacidad Indica si el usuario posee discapacidad.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function seleccionarTengoDiscapacidad(posee_discapacidad) {
    $('#contenedor-discapacidad').empty();
    if (posee_discapacidad) {
        $('#contenedor-discapacidad').append(`
            <div class="col-12 p-4 border rounded-3">
                <div class="row align-items-center pb-2">
                    <div class="col-12">
                        <label class="form-label fw-semibold">Discapacidad</label>
                    </div>
                    <div class="col-6">
                        ${crearMultiselect({
                            opciones: discapacidades,
                            id: 'select_discapacidades',
                            name: 'select_discapacidades',
                            class: 'input-dinamico',
                            input_container_class: 'mb-0',
                            placeholder: 'Discapacidad',
                            onchange: 'seleccionarDiscapacidad(this.value)',
                            required: true,
                        })}
                    </div>
                    <div class="col-6" id="contenedor-otra-discapacidad"></div>
                </div>
            </div>
        `);
        inizializarMultiselect();
    }
}

/**
 * Función para seleccionar otra discapacidad.
 * 
 * @param {number} discapacidad_id ID de la discapacidad seleccionada.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function seleccionarDiscapacidad(discapacidad_id) {
    let discapacidades_seleccionadas = $('#select_discapacidades').val() || [];
    if (discapacidades_seleccionadas.includes('5')) {
        let otra_discapacidad_existente = $('#otra_discapacidad').length > 0;
        if (!otra_discapacidad_existente) {
            $('#contenedor-otra-discapacidad').append(`
                ${crearInput({
                    id: 'otra_discapacidad',
                    name: 'otra_discapacidad',
                    class: 'input-dinamico',
                    input_container_class: 'mb-0',
                    label: '¿Cuál?',
                    required: true,
                })}
            `);
        }
    } else {
        $('#contenedor-otra-discapacidad').empty();
    }
}

/**
 * Función para crear el perfil manualmente.
 * 
 * @returns {void}
 * @author José Manuel Jiménez
 */
function crearPerfilManualmente() {
    $('#contenedor-campos-perfil').removeClass('d-none');
    $('#contenedor-opciones-crear-ia').addClass('d-none');
}

/**
 * Función para manejar el cambio de archivo.
 * 
 * @param {HTMLElement} archivo Elemento HTML del archivo cargado.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Sergio Vargas
 */
function cambioArchivo(archivo) {
    let elemento_html_archivo = $(archivo).prop('id');
    const PUEDE_USAR_IA = (typeof revision_hv_ia !== 'undefined' && revision_hv_ia)
        && (typeof creditos_disponibles === 'undefined' || creditos_disponibles);

    if (PUEDE_USAR_IA && elemento_html_archivo == 'hoja_vida') {
        generarPerfilHVPorIA(elemento_html_archivo);
    }
}

/**
 * Función para guardar los datos actuales del formulario en el localStorage del navegador.
 * 
 * @returns {void}
 * @author Esperanza Olivo
 */
function guardarBorradorEnLocalStorage(forzar_guardado = false) {
    if (cambiando_paso && !forzar_guardado) return;

    var borrador_id = 'borrador_completar_datos_' + USUARIO.id;
    var paso_activo = $('#formulario .nav-pasos.active').first().attr('href')?.replace('#tab-pasos-usuario-', '') || 'datos-generales';

    var datos = {
        paso_actual: paso_activo,
        datos_generales: {
            nombres: $('#nombres').val(),
            apellidos: $('#apellidos').val(),
            telefono: $('#telefono').val(),
            direccion: $('#direccion').val(),
            fecha_nacimiento: $('#fecha_nacimiento').val(),
            genero_id: $('#genero_id').val(),
            pais_id: $('#pais_id').val(),
            departamento_id: $('#departamento_id').val(),
            ciudad_id: $('#ciudad_id').val(),
            tipo_documento_id: $('#tipo_documento_id').val(),
            documento: $('#documento').val(),
            aceptar_politicas: $('#aceptar_politicas').is(':checked'),
            aceptar_teminos_condiciones: $('#aceptar_teminos_condiciones').is(':checked'),
        },
        datos_acceso: {
            usuario_verificado: usuario_verificado,
            codigo_enviado: codigo_verificacion_enviado || !$('#contenedor-codigo-confirmacion').hasClass('d-none'),
        },
        perfil_laboral: {
            salario: $('#salario').val(),
            salario_maximo: $('#salario_maximo').val(),
            tipo_salario: $('input[name="tipo_salario"]:checked').val(),
            habilidades: $('#select_habilidades').val(),
            herramientas: $('#select_herramientas_tecnologicas').val(),
            no_experiencia: $('#no_experiencia').is(':checked'),
        },
        estudios: estudios,
        experiencias: experiencias,
        timestamp: Date.now()
    };    
    localStorage.setItem(borrador_id, JSON.stringify(datos));
}

/**
 * Recupera los datos del localStorage y los restaura en el formulario.
 * 
 * @returns {boolean} true si se restauró con éxito, false en caso contrario.
 * @author Esperanza Olivo
 */
function restaurarBorradorLocalStorage() {
    if (borrador_restaurado) return false;

    var borrador_id = 'borrador_completar_datos_' + USUARIO.id;
    var borrador = localStorage.getItem(borrador_id);
    if (!borrador) return false;

    var datos_usuario = JSON.parse(borrador);
    var tiempo_expiracion = 24 * 60 * 60 * 1000; 

    if (Date.now() - datos_usuario.timestamp > tiempo_expiracion) {
        localStorage.removeItem(borrador_id);
        return false;
    }

    if (datos_usuario.datos_generales) {
        $('#nombres').val(datos_usuario.datos_generales.nombres || '');
        $('#apellidos').val(datos_usuario.datos_generales.apellidos || '');
        $('#telefono').val(datos_usuario.datos_generales.telefono || '');
        $('#direccion').val(datos_usuario.datos_generales.direccion || '');
        if (datos_usuario.datos_generales.fecha_nacimiento) {
            $('#fecha_nacimiento')[0]?._flatpickr?.setDate(datos_usuario.datos_generales.fecha_nacimiento, false);
        }
        if (datos_usuario.datos_generales.genero_id) {
            $('#genero_id').val(datos_usuario.datos_generales.genero_id).trigger('change');
        }
        if (datos_usuario.datos_generales.tipo_documento_id) {
            $('#tipo_documento_id').val(datos_usuario.datos_generales.tipo_documento_id).trigger('change');
        }
        $('#documento').val(datos_usuario.datos_generales.documento || '');

        if (datos_usuario.datos_generales.pais_id) {
            establecerDatosComponentePaisesDepartamentosCiudades({
                pais: { html_id: 'pais_id', value: datos_usuario.datos_generales.pais_id },
                departamento: { html_id: 'departamento_id', value: datos_usuario.datos_generales.departamento_id },
                ciudad: { html_id: 'ciudad_id', value: datos_usuario.datos_generales.ciudad_id },
            });
        }

        $('#aceptar_politicas').prop('checked', datos_usuario.datos_generales.aceptar_politicas);
        $('#aceptar_teminos_condiciones').prop('checked', datos_usuario.datos_generales.aceptar_teminos_condiciones);
        validarPoliticas();
    }

    if (datos_usuario.datos_acceso) {
        if (datos_usuario.datos_acceso.codigo_enviado && !datos_usuario.datos_acceso.usuario_verificado) {
            codigo_verificacion_enviado = true;
            $('#contenedor-mensaje-verificar').addClass('d-none');
            $('#contenedor-codigo-confirmacion').removeClass('d-none col-lg-6');
            $('#contenedor-reenviar-mensaje').removeClass('d-none');
            $('#contenedor-boton-reenviar-mensaje').removeClass('d-none');
            $('#contenedor-boton-verificar-correo').addClass('d-none');
            $('#contenedor-info-mensaje-enviado').addClass('d-none');
            $('#contenedor-mensaje-enviado').addClass('d-none');
        }

        if (datos_usuario.datos_acceso.usuario_verificado) {
            usuario_verificado = true;
            mostrarAlertasUsuarioVerificado();
        }
    }

    if (datos_usuario.estudios?.length > 0) {
        estudios = datos_usuario.estudios;
        mostrarNivelesEducativos();
    }

    if (datos_usuario.experiencias?.length > 0) {
        experiencias = datos_usuario.experiencias;
        mostrarExperienciasLaborales();
    }

    if (datos_usuario.paso_actual) {
        habilitarPasosNavegacion(datos_usuario.paso_actual);
    }

    borrador_restaurado = true;
    return true;
}

/**
 * Habilita las pestañas del formulario y navega hacia ellas.
 * @param {string} paso_id Identificador del paso.
 * @returns {void}
 * @author Esperanza Olivo
 * @author Jair Carvajal
 */
function habilitarPasosNavegacion(paso_id) {
    var pasos = ['datos-generales', 'datos-acceso', 'perfil-laboral'];
    var paso_indice = pasos.indexOf(paso_id);

    for (var i = 0; i <= paso_indice; i++) {
        var selector_paso = '#titulo-tab-pasos-usuario-' + pasos[i];
        $(selector_paso).prop('disabled', false);

        if (paso_id !== 'datos-generales') {
            setTimeout(function() {
                $('#titulo-tab-pasos-usuario-' + paso_id).click();
            }, 600);
        }
    }

    if (paso_id === 'perfil-laboral') {
        $('#contenedor-contrasenas').addClass('d-none');
    }
}

/**
 * Función para ejecutar el auto-guardado.
 * 
 * @returns {void}
 * @author Esperanza Olivo
 * @author Jair Carvajal
 */
function iniciarAutoGuardado() {
    $('#formulario').on('input change', 'input, select, textarea', function() {
        if (cambiando_paso) return;
        clearTimeout(temporizador_auto_guardado);
        temporizador_auto_guardado = setTimeout(function() {
            if (!cambiando_paso) {
                guardarBorradorEnLocalStorage();
            }
        }, 2000);
    });
}

