$(document).ready(function () {
    if (window.innerWidth > 768) return;

    const TITULOS_PASOS = {
        'datos-generales': 'Datos generales',
        'datos-acceso': 'Datos de acceso',
        'perfil-laboral': 'Hoja de vida',
    };

    $(document).on('shown.bs.tab', 'button[data-bs-toggle="tab"]', function () {
        var pestana_id = $(this).attr('href').replace('#tab-pasos-usuario-', '');
        var titulo = TITULOS_PASOS[pestana_id] || '';
        $('#titulo-paso-movil').text(titulo);
    });

    var esta_movimiento = false;

    /**
     * Verifica si el campo está dentro de un modal
     * @param {HTMLElement} campo - El campo a verificar si esta dentro de la modal
     * @returns {boolean}
     * @author Jair Carvajal
     */
    function estaEnModal(campo) {
        return $(campo).closest('.modal').length > 0;
    }

    /**
     * Hace scroll suave para posicionar el .input-container del campo en el top
     * @param {HTMLElement} campo - El campo a verificar si esta dentro de la modal
     * @param {Function} ejecutar_desplazamiento - Función a ejecutar después del scroll
     * @author Jair Carvajal
     */
    function scrollAlCampo(campo, ejecutar_desplazamiento) {
        if (estaEnModal(campo)) {
            if (ejecutar_desplazamiento) callback();
            return;
        }

        var contenedor = $(campo).closest('.input-container')[0];
        if (!contenedor) {
            if (ejecutar_desplazamiento) callback();
            return;
        }

        esta_movimiento = true;
        contenedor.scrollIntoView({ behavior: 'smooth', block: 'start' });

        setTimeout(function () {
            esta_movimiento = false;
            if (ejecutar_desplazamiento) callback();
        }, 400);
    }

    // Scroll para cualquier Select2 en cualquier paso
    $(document).on('select2:open', function (evento) {
        if (!esta_movimiento) {
            scrollAlCampo(evento.target);
        }
    });

    // Scroll para cualquier input, textarea o select en cualquier paso
    document.addEventListener('focusin', function (evento) {
        var etiqueta = evento.target.tagName;
        if (etiqueta !== 'INPUT' && etiqueta !== 'TEXTAREA' && etiqueta !== 'SELECT') return;
        if (evento.target.type === 'hidden') return;

        // Si es un flatpickr, cerrar, hacer scroll y reabrir
        if (evento.target._flatpickr) {
            var flatpickr_instancia = evento.target._flatpickr;
            flatpickr_instancia.close();
            scrollAlCampo(evento.target, function () {
                flatpickr_instancia.open();
            });
            return;
        }

        if (!esta_movimiento) {
            scrollAlCampo(evento.target);
        }
    });
});

