/**
 * Función para abrir el modal de agregar o editar un nivel educativo.
 * 
 * @param {number|null} index Índice del nivel educativo a editar. Si es null, se agrega un nuevo nivel educativo.
 * @return {void}
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function editarNivelEducativo(index) {
    indice_editar = index;
    let estudio = estudios[index];
    $('#titulo').val(estudio.titulo);
    $('#institucion_educativa').val(estudio.institucion_educativa);
    $('#nivel_educativo_id').val(estudio.nivel_educativo_id).trigger('change');
    $('#jornada').val(estudio.jornada || '').trigger('change');
    establecerDatosComponentePaisesDepartamentosCiudades({
        pais: { html_id: 'estudio_pais_id', value: estudio.pais_id },
        departamento: { html_id: 'estudio_departamento_id', value: estudio.departamento_id },
        ciudad: { html_id: 'estudio_ciudad_id', value: estudio.ciudad_id },
    });
    $('#certificado').attr('data-base64', estudio.certificado || '');
    $('#modal-agregar-nivel-educativo').modal('show');
    $('#cursando_estudios').prop('checked', !estudio.graduado).trigger('change');
    let fecha_inicio_estudio = $('#fecha_inicio_estudio').length ? $('#fecha_inicio_estudio')[0]._flatpickr : null;
    if (fecha_inicio_estudio) {
        fecha_inicio_estudio.setDate(estudio.fecha_inicio);
    }
    if ($('#fecha_fin_estudio').length && $('#fecha_fin_estudio')[0]._flatpickr) {
        $('#fecha_fin_estudio')[0]._flatpickr.setDate(estudio.fecha_fin || '');
    }
    $('#modal-agregar-nivel-educativo').find('input.error , select.error , textarea.error').removeClass('error');
    $('#modal-agregar-nivel-educativo').find('label.error').remove();
}

/**
 * Función para eliminar un nivel educativo.
 * 
 * @param {number} index Índice del nivel educativo a eliminar.
 * @return {void}
 * @author José Manuel Jiménez
 */
function eliminarNivelEducativo(index) {
    estudios.splice(index, 1);
    mostrarNivelesEducativos();
}

/**
 * Función para ver el certificado de estudio en una nueva ventana.
 * 
 * @param {number} index Índice del nivel educativo cuyo certificado se desea ver.
 * @return {void}
 * @author José Manuel Jiménez
 */
function verCertificadoEstudio(index) {
    let certificado = estudios[index].certificado;
    if (certificado) {
        try {
            let certificado_base64 = certificado.split(',')[1] || certificado;
            const binaryString = atob(certificado_base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            let blob = new Blob([bytes], { type: 'application/pdf' });
            let url = URL.createObjectURL(blob);
            let nuevaVentana = window.open(url, '_blank');
            if (nuevaVentana) {
                nuevaVentana.onload = function() {
                    setTimeout(() => URL.revokeObjectURL(url), 1000);
                };
            }
        } catch (error) {
            mostrarToast('danger', 'Error al abrir el certificado.', '', '', 'bi bi-exclamation-lg');
        }
    } else {
        mostrarToast('danger', 'No se encontró el certificado de estudio.', '', '', 'bi bi-exclamation-lg');
    }
}

