 */
function seleccionarNivelEducacionAplicante(nivel) {
    $('#niveles').empty();
    let niveles = [];
    if (nivel === 'Básica y media') {
        $('#niveles').append(`
            <div class="row align-items-center">
                <div class="col-12">
                    ${crearSelect2({
                        opciones: niveles_basica_primaria,
                        id: 'nivel_estudio_id',
                        name: 'nivel_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Nivel',
                        required: true,
                    })}
                </div>
            </div>
        `);
    } else if (nivel === 'Superior') {
        $('#niveles').append(`
            <div class="row align-items-center">
                <div class="col-6">
                    ${crearSelect2({
                        opciones: niveles_superior,
                        id: 'nivel_estudio_id',
                        name: 'nivel_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Nivel',
                        required: true,
                    })}
                </div>
                <div class="col-6">
                    ${crearSelect2({
                        opciones: areas_estudio,
                        id: 'area_estudio_id',
                        name: 'area_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Área de estudio',
                        required: true,
                    })}
                </div>
            </div>
        `);
    }
    actualizarSelect2();
}

