function editarExperienciaLaboral(index) {
    indice_editar = index;
    let experiencia = experiencias[index];
    certificados_laborales = experiencia.certificados || [];
    $('#cargo').val(experiencia.cargo);
    $('#empresa').val(experiencia.empresa);
    $(`input[name="cargo_modalidad_trabajo_id"][value="${experiencia.modalidad_trabajo_id}"]`).prop('checked', true).trigger('change');
    establecerDatosComponentePaisesDepartamentosCiudades({
        pais: { html_id: 'experiencia_pais_id', value: experiencia.pais_id },
        departamento: { html_id: 'experiencia_departamento_id', value: experiencia.departamento_id },
        ciudad: { html_id: 'experiencia_ciudad_id', value: experiencia.ciudad_id },
    });
    $('#funciones_experiencia').val(experiencia.funciones);
    $(`input[name="cargo_jornada_id"][value="${experiencia.jornada_id}"]`).prop('checked', true);
    establecerDatosClassicEditor('funciones_principales', experiencia.funciones_principales || '');
    $('#certificado_laboral').attr('data-base64', experiencia.certificado || '');
    $('#modal-agregar-experiencia-laboral').one('shown.bs.modal', function () {
        $('#actualmente_trabajo').prop('checked', experiencia.actualmente_trabajo == 1).trigger('change');
        let fecha_inicio = $('#fecha_inicio_experiencia').length ? $('#fecha_inicio_experiencia')[0]._flatpickr : null;
        if (fecha_inicio) {
            fecha_inicio.setDate(experiencia.fecha_inicio, false);
        }
        if ($('#fecha_fin_experiencia').length && $('#fecha_fin_experiencia')[0]._flatpickr) {
            $('#fecha_fin_experiencia')[0]._flatpickr.setDate(experiencia.fecha_fin || '', false);
        }
    });
    $('#modal-agregar-experiencia-laboral').modal('show');
    $('#modal-agregar-experiencia-laboral').find('input.error , select.error , textarea.error').removeClass('error');
    $('#modal-agregar-experiencia-laboral').find('label.error').remove();
}

/**
 * Función para eliminar una experiencia laboral.
 * 
 * @param {number} index Índice de la experiencia laboral a eliminar.
 * @return {void}
 * @author José Manuel Jiménez
 */
function eliminarExperienciaLaboral(index) {
    experiencias.splice(index, 1);
    mostrarExperienciasLaborales();
}

function mostrarCertificadosLaborales() {
    $('#tbody-certificados-laborales').empty();
    if (certificados_laborales.length > 0) {
        certificados_laborales.forEach((certificado, index) => {
            $('#tbody-certificados-laborales').append(`
                <tr id="certificado-laboral-${index}">
                    <td>
                        <span onclick="verCertificadoExperiencia(${index})">
                            ${certificado.nombre}
                        </span>
                    </td>
                    <td>
                        ${crearBoton({
                            clases: 'btn-outline-danger btn-circle',
                            texto: '<i class="bi bi-trash-fill"></i>',
                            onclick: `eliminarCertificadoLaboral(${index})`
                        })}
                    </td>
                </tr>
            `);
        });
    }
}

function eliminarCertificadoLaboral(index) {
    certificados_laborales.splice(index, 1);
    mostrarCertificadosLaborales();
}

/**
 * Función para ver el certificado de experiencia laboral en una nueva ventana.
 * @param {number} index Índice de la experiencia laboral cuyo certificado se desea ver.
 * @return {void}
 * @author José Manuel Jiménez
 */
function verCertificadoExperiencia(index) {
    let certificado = certificados_laborales[index].certificado;
    if (certificado) {
        try {
            let certificado_base64 = certificado.split(',')[1] || certificado;
            const binaryString = atob(certificado_base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            let blob = new Blob([bytes], { type: 'application/pdf' });
            let url = URL.createObjectURL(blob);
            let nuevaVentana = window.open(url, '_blank');
            if (nuevaVentana) {
                nuevaVentana.onload = function() {
                    setTimeout(() => URL.revokeObjectURL(url), 1000);
                };
            }
        } catch (error) {
            mostrarToast('danger', 'Error al abrir el certificado.', '', '', 'bi bi-exclamation-lg');
        }
    } else {
        mostrarToast('danger', 'No se encontró el certificado de experiencia laboral.', '', '', 'bi bi-exclamation-lg');
    }
}

/**
 * Función para seleccionar si el usuario no tiene experiencia laboral.
 *
 * @param {boolean} marcado Indica si el checkbox "No tengo experiencia laboral" está seleccionado.
 * @return {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function seleccionarNoTengoExperiencia(marcado) {
    if (marcado) {
        $('#btn-agregar-experiencia-laboral').addClass('d-none');
    } else {
        $('#btn-agregar-experiencia-laboral').removeClass('d-none');
    }
}

