function inicializarFlatpickr() {
    $(".flatpickr").each(function () {
        if (this._flatpickr) return;
        var input = $(this);
        var id = input.attr("id");
        var minima_fecha = input.attr("min");
        var maxima_fecha = input.attr("max");
        var fecha_selector = input.flatpickr({
            altInput: true,
            altFormat: "d/m/Y",
            dateFormat: "Y-m-d",
            enableTime: false,
            time_24hr: true,
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: "rounded-2 text-body-2 bg-transparent input-dinamico",
            onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (instancia.altInput && id) {
                    instancia.altInput.id = `${id}_alt`;
                }
            }
        });
    });

    $(".flatpickr-month-year").each(function () {
        if (this._flatpickr) return;
        var input = $(this);
        var id = input.attr("id");
        var minima_fecha = input.attr("min");
        var maxima_fecha = input.attr("max");

        if (typeof monthSelectPlugin === 'undefined') {
            var fecha_selector = input.flatpickr({
                altInput: true,
                altFormat: "m/Y",
                dateFormat: "Y-m-d",
                enableTime: false,
                time_24hr: true,
                minDate: minima_fecha || undefined,
                maxDate: maxima_fecha || undefined,
                altInputClass: "rounded-2 text-body-2 bg-transparent input-dinamico",
                onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                    if (instancia.altInput && id) {
                        instancia.altInput.id = `${id}_alt`;
                    }
                    // Ocultar los días del calendario
                    var calendario = instancia.calendarContainer;
                    if (calendario) {
                        var contenedor_dias = calendario.querySelector('.flatpickr-days');
                        if (contenedor_dias) {
                            contenedor_dias.style.display = 'none';
                        }
                    }
                },
                onChange: function(fechas_seleccionadas, cadena_fecha, instancia) {
                    // Establecer siempre el día 01 del mes seleccionado
                    if (fechas_seleccionadas.length > 0) {
                        var fecha_seleccionada = fechas_seleccionadas[0];
                        var anio = fecha_seleccionada.getFullYear();
                        var mes = fecha_seleccionada.getMonth();
                        var fecha_primer_dia = new Date(anio, mes, 1);
                        instancia.setDate(fecha_primer_dia, false);
                    }
                },
                onMonthChange: function(fechas_seleccionadas, cadena_fecha, instancia) {
                    var fecha_actual = instancia.currentYear && instancia.currentMonth !== undefined
                        ? new Date(instancia.currentYear, instancia.currentMonth, 1)
                        : new Date();
                    instancia.setDate(fecha_actual, true);
                    instancia.close();
                }
            });
        } else {
            var fecha_selector = input.flatpickr({
                plugins: [
                    new monthSelectPlugin({
                        shorthand: true,
                        dateFormat: "Y-m-d",
                        altFormat: "F Y",
                        theme: "light"
                    })
                ],
                altInput: true,
                altFormat: "m/Y",
                dateFormat: "Y-m-d",
                minDate: minima_fecha || undefined,
                maxDate: maxima_fecha || undefined,
                altInputClass: "rounded-2 text-body-2 bg-transparent input-dinamico",
                onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                    if (instancia.altInput && id) {
                        instancia.altInput.id = `${id}_alt`;
                    }
                },
                onChange: function(fechas_seleccionadas, cadena_fecha, instancia) {
                    if (fechas_seleccionadas.length > 0) {
                        var fecha_seleccionada = fechas_seleccionadas[0];
                        var anio = fecha_seleccionada.getFullYear();
                        var mes = fecha_seleccionada.getMonth();
                        var fecha_primer_dia = new Date(anio, mes, 1);
                        instancia.setDate(fecha_primer_dia, false);
                    }
                }
            });
        }
    });
    $(`.flatpickr-time`).each(function () {
        if (this._flatpickr) return;
        var input = $(this);
        var minima_fecha = input.attr("min");
        var maxima_fecha = input.attr("max");
        input.flatpickr({
            altInput: true,
            altFormat: "d/m/Y H:i:ss",
            dateFormat: "Y-m-d H:i:ss",
            enableTime: true,
            time_24hr: true,
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: "rounded-2 text-body-2 bg-transparent input-dinamico",
        });

