$(document).ready(function() {

    inicializarFlatpickr();

    $(document).on('focus', '.flatpickr-duration + .flatpickr-input', function() {
        $(this).siblings('.label-flotante').addClass('label-flotante-superior');
    });

    $(document).on('blur', '.flatpickr-duration + .flatpickr-input', function() {
        if (!$(this).val() && !$(this).attr('placeholder')) {
             $(this).siblings('.label-flotante').removeClass('label-flotante-superior');
        }
    });

    // Inicialización de componentes checkbox para seleccionar todos los checkbox de un grupo de checkbox.
    $('.checkbox-indeterminate').prop('indeterminate', true);

