        }, 1000);
    }
}

/**
 * Inicializa el selector de mes y año (flatpickr) para un elemento específico por ID.
 * Usa la misma configuración que inicializarFlatpickr() pero de forma dirigida,
 * evitando inicializar elementos en otros modales ocultos.
 *
 * @param {string} elemento_id ID del input a inicializar.
 * @returns {void}
 * @author Jair Carvajal
 */
function inicializarSelectorFechaEnElemento(elemento_id) {
    var el = document.getElementById(elemento_id);
    if (!el || el._flatpickr) return;
    var input = $(el);
    var minima_fecha = input.attr('min');
    var maxima_fecha = input.attr('max');
    if (typeof monthSelectPlugin !== 'undefined') {
        input.flatpickr({
            plugins: [
                new monthSelectPlugin({
                    shorthand: true,
                    dateFormat: 'Y-m-d',
                    altFormat: 'F Y',
                    theme: 'light',
                }),
            ],
            altInput: true,
            altFormat: 'm/Y',
            dateFormat: 'Y-m-d',
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: 'rounded-2 text-body-2 bg-transparent input-dinamico',
            onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (instancia.altInput && elemento_id) {
                    instancia.altInput.id = elemento_id + '_alt';
                }
            },
            onChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (fechas_seleccionadas.length > 0) {
                    var fecha_seleccionada = fechas_seleccionadas[0];
                    var anio = fecha_seleccionada.getFullYear();
                    var mes = fecha_seleccionada.getMonth();
                    instancia.setDate(new Date(anio, mes, 1), false);
                }
            },
        });
    } else {
        input.flatpickr({
            altInput: true,
            altFormat: 'm/Y',
            dateFormat: 'Y-m-d',
            enableTime: false,
            time_24hr: true,
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: 'rounded-2 text-body-2 bg-transparent input-dinamico',
            onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (instancia.altInput && elemento_id) {
                    instancia.altInput.id = elemento_id + '_alt';
                }
                var calendario = instancia.calendarContainer;
                if (calendario) {
                    var contenedor_dias = calendario.querySelector('.flatpickr-days');
                    if (contenedor_dias) contenedor_dias.style.display = 'none';
                }
            },
            onChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (fechas_seleccionadas.length > 0) {
                    var fecha_seleccionada = fechas_seleccionadas[0];
                    var anio = fecha_seleccionada.getFullYear();
                    var mes = fecha_seleccionada.getMonth();
                    instancia.setDate(new Date(anio, mes, 1), false);
                }
            },
            onMonthChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                var fecha_actual = instancia.currentYear && instancia.currentMonth !== undefined
                    ? new Date(instancia.currentYear, instancia.currentMonth, 1)
                    : new Date();
                instancia.setDate(fecha_actual, true);
                instancia.close();
            },
        });
    }
}

