/**
 * Inicializa el selector de mes y año (flatpickr) para un elemento específico por ID.
 * Usa la misma configuración que inicializarFlatpickr() pero de forma dirigida,
 * evitando inicializar elementos en otros modales ocultos.
 *
 * @param {string} elemento_id ID del input a inicializar.
 * @returns {void}
 * @author Jair Carvajal
 */
function inicializarSelectorFechaEnElemento(elemento_id) {
    var el = document.getElementById(elemento_id);
    if (!el || el._flatpickr) return;
    var input = $(el);
    var minima_fecha = input.attr('min');
    var maxima_fecha = input.attr('max');
    if (typeof monthSelectPlugin !== 'undefined') {
        input.flatpickr({
            plugins: [
                new monthSelectPlugin({
                    shorthand: true,
                    dateFormat: 'Y-m-d',
                    altFormat: 'F Y',
                    theme: 'light',
                }),
            ],
            altInput: true,
            altFormat: 'm/Y',
            dateFormat: 'Y-m-d',
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: 'rounded-2 text-body-2 bg-transparent input-dinamico',
            onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (instancia.altInput && elemento_id) {
                    instancia.altInput.id = elemento_id + '_alt';
                }
            },
            onChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (fechas_seleccionadas.length > 0) {
                    var fecha_seleccionada = fechas_seleccionadas[0];
                    var anio = fecha_seleccionada.getFullYear();
                    var mes = fecha_seleccionada.getMonth();
                    instancia.setDate(new Date(anio, mes, 1), false);
                }
            },
        });
    } else {
        input.flatpickr({
            altInput: true,
            altFormat: 'm/Y',
            dateFormat: 'Y-m-d',
            enableTime: false,
            time_24hr: true,
            minDate: minima_fecha || undefined,
            maxDate: maxima_fecha || undefined,
            altInputClass: 'rounded-2 text-body-2 bg-transparent input-dinamico',
            onReady: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (instancia.altInput && elemento_id) {
                    instancia.altInput.id = elemento_id + '_alt';
                }
                var calendario = instancia.calendarContainer;
                if (calendario) {
                    var contenedor_dias = calendario.querySelector('.flatpickr-days');
                    if (contenedor_dias) contenedor_dias.style.display = 'none';
                }
            },
            onChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                if (fechas_seleccionadas.length > 0) {
                    var fecha_seleccionada = fechas_seleccionadas[0];
                    var anio = fecha_seleccionada.getFullYear();
                    var mes = fecha_seleccionada.getMonth();
                    instancia.setDate(new Date(anio, mes, 1), false);
                }
            },
            onMonthChange: function (fechas_seleccionadas, cadena_fecha, instancia) {
                var fecha_actual = instancia.currentYear && instancia.currentMonth !== undefined
                    ? new Date(instancia.currentYear, instancia.currentMonth, 1)
                    : new Date();
                instancia.setDate(fecha_actual, true);
                instancia.close();
            },
        });
    }
}

function abrirModalNivelEducativo() {
    indice_editar = null;
    $('#modal-agregar-nivel-educativo').one('shown.bs.modal', function () {
        $('#cursando_estudios').prop('checked', false);
        seleccionarGraduadoCursando();
        limpiarFormulario('formulario-nivel-educativo');
    });
    $('#modal-agregar-nivel-educativo').modal('show');
}

/**
 * Función para seleccionar un nivel de educación.
 *
 * @param {string} nivel Nivel de educación.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function seleccionarNivelEducacionAplicante(nivel) {
    $('#niveles').empty();
    let niveles = [];
    if (nivel === 'Básica y media') {
        $('#niveles').append(`
            <div class="row align-items-center">
                <div class="col-12">
                    ${crearSelect2({
                        opciones: niveles_basica_primaria,
                        id: 'nivel_estudio_id',
                        name: 'nivel_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Nivel',
                        required: true,
                    })}
                </div>
            </div>
        `);
    } else if (nivel === 'Superior') {
        $('#niveles').append(`
            <div class="row align-items-center">
                <div class="col-6">
                    ${crearSelect2({
                        opciones: niveles_superior,
                        id: 'nivel_estudio_id',
                        name: 'nivel_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Nivel',
                        required: true,
                    })}
                </div>
                <div class="col-6">
                    ${crearSelect2({
                        opciones: areas_estudio,
                        id: 'area_estudio_id',
                        name: 'area_estudio_id',
                        class: 'input-dinamico',
                        input_container_class: 'mb-4',
                        label: 'Área de estudio',
                        required: true,
                    })}
                </div>
            </div>
        `);
    }
    actualizarSelect2();
}

/**
 * Función para seleccionar si el usuario es graduado o está cursando estudios.
 * 
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
*/
function seleccionarGraduadoCursando() {
    let graduado_cursando_estudios = $('#cursando_estudios').prop('checked');
    let fecha_inicio_existente = $('#fecha_inicio_estudio').length ? $('#fecha_inicio_estudio')[0]._flatpickr : null;
    if (fecha_inicio_existente) fecha_inicio_existente.destroy();
    let fecha_fin_existente = $('#fecha_fin_estudio').length ? $('#fecha_fin_estudio')[0]._flatpickr : null;
    if (fecha_fin_existente) fecha_fin_existente.destroy();
    $('#fechas-cursando-estudios').empty();
    if (graduado_cursando_estudios) {
        $('#fechas-cursando-estudios').append(`
            <div class="row align-items-center">
                <div class="col-12 col-md-6 mt-2">
                    ${crearSelectorMesAnio({
                        id: 'fecha_inicio_estudio',
                        name: 'fecha_inicio_estudio',
                        placeholder: 'mm/yyyy',
                        disabled: false,
                        required: true,
                        input_container_class: 'mb-4',
                        label: 'Fecha de inicio',
                        icono2: '<i class="bi bi-calendar4 input-icono2 pointer"></i>',
                    })}
                </div>

